  updateProduct,
  deleteProductById,
  getOrdersByVendor,
  updateOrderStatus,
} from "../utils/api";

export default function VendorDashboard({ vendor }) {
  const [products, setProducts] = useState([]);
  const [orders, setOrders] = useState([]);
  const [form, setForm] = useState({
    id: null,
    name: "",
    description: "",
    price: "",
    stockQuantity: "",
    category: "",
    imageUrl: "",
  });
  const [editing, setEditing] = useState(false);

  const navigate = useNavigate(); 

  // ✅ Logout
  const handleLogout = () => {
    localStorage.removeItem("token"); 
    localStorage.removeItem("vendor"); 
    navigate("/"); 
  };

  // ✅ Fetch Products
  const fetchProducts = async () => {
    if (!vendor) return;
    try {
      const data = await getProductsByVendor(vendor.id);
      setProducts(data);
    } catch (err) {
      console.error("Error fetching products", err);
    }
  };

  // ✅ Fetch Orders
  const fetchOrders = async () => {
    if (!vendor) return;
    try {
      const data = await getOrdersByVendor(vendor.id);
      setOrders(data);
    } catch (err) {
      console.error("Error fetching orders", err);
    }
  };

  useEffect(() => {
    fetchProducts();
    fetchOrders();
  }, [vendor]);

  // ✅ Handle form input
  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  // ✅ Submit form (create or update product)
  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      if (editing) {
        await updateProduct(form.id, form);
      } else {
        await createProduct(vendor.id, form);
      }
      setForm({
        id: null,
        name: "",
        description: "",
        price: "",
        stockQuantity: "",
        category: "",
        imageUrl: "",
      });
      setEditing(false);
      fetchProducts();
    } catch (err) {
      console.error("Error saving product", err);
    }
  };

  // ✅ Edit product
  const handleEdit = (product) => {
    setForm(product);
    setEditing(true);
  };

  // ✅ Delete product
  const handleDelete = async (id) => {
    try {
      await deleteProductById(id);
      fetchProducts();
    } catch (err) {
      console.error("Error deleting product", err);
    }
  };

  // ✅ Update order status
  const handleOrderStatus = async (orderId, status) => {
    try {
      await updateOrderStatus(orderId, status);
      fetchOrders();
    } catch (err) {
      console.error("Error updating order", err);
    }
  };

  return (
    <div className="vendor-dashboard">
      {/* Header */}
      <div className="dashboard-header">
        <h2>Welcome, {vendor?.name}</h2>
        <button className="logout-btn" onClick={handleLogout}>
          Logout
        </button>
      </div>

      {/* Products Section */}
      <section className="products-section">
        <h3>Manage Products</h3>
        <form className="product-form" onSubmit={handleSubmit}>
          <input
            type="text"
            name="name"
            placeholder="Name"
            value={form.name}
            onChange={handleChange}
            required
          />
          <input
            type="text"
            name="description"
            placeholder="Description"
            value={form.description}
            onChange={handleChange}
            required
          />
          <input
            type="number"
            name="price"
            placeholder="Price"
            value={form.price}
            onChange={handleChange}
            required
          />
          <input
            type="number"
            name="stockQuantity"
            placeholder="Stock Quantity"
            value={form.stockQuantity}
            onChange={handleChange}
            required
          />
          <input
            type="text"
            name="category"
            placeholder="Category"
            value={form.category}
            onChange={handleChange}
            required
          />
          <input
            type="text"
            name="imageUrl"
            placeholder="Image URL"
            value={form.imageUrl}
            onChange={handleChange}
            required
          />
          <button type="submit" className="submit-btn">
            {editing ? "Update Product" : "Add Product"}
          </button>
        </form>

        <ul className="product-list">
          {products.map((p) => (
            <li key={p.id} className="product-item">
              <img src={p.imageUrl} alt={p.name} />
              <div>
                <h4>{p.name}</h4>
                <p>{p.description}</p>
                <p><b>Price:</b> ₹{p.price}</p>
                <p><b>Stock:</b> {p.stockQuantity}</p>
                <p><b>Category:</b> {p.category}</p>
              </div>
              <div className="product-actions">
                <button onClick={() => handleEdit(p)} className="edit-btn">Edit</button>
                <button onClick={() => handleDelete(p.id)} className="delete-btn">Delete</button>
              </div>
            </li>
          ))}
        </ul>
      </section>

      {/* Orders Section */}
      <section className="orders-section">
        <h3>Customer Orders</h3>
        <ul className="order-list">
          {orders.map((o) => (
            <li key={o.id} className="order-item">
              <h4>Order #{o.id}</h4>
              <p><b>Customer:</b> {o.customerName} ({o.customerEmail})</p>
              <p><b>Total:</b> ₹{o.totalAmount}</p>
              <p><b>Status:</b> {o.status}</p>
              <ul className="order-items">
                {o.orderItems.map((item) => (
                  <li key={item.id}>
                    {item.product.name} - Qty: {item.quantity} - ₹{item.subtotal}
                  </li>
                ))}
              </ul>
              <div className="order-actions">
                <button onClick={() => handleOrderStatus(o.id, "COMPLETED")} className="complete-btn">Mark Completed</button>
                <button onClick={() => handleOrderStatus(o.id, "CANCELLED")} className="cancel-btn">Cancel</button>
              </div>
            </li>
          ))}
        </ul>
      </section>
    </div>
  );
}
